<template>
  <main class="chat-page">
    <aside class="chat-sidebar">
      <RouterLink class="chat-brand" to="/chat"><i class="pulse" /> AI 应用服务平台</RouterLink>
      <button class="new-chat" @click="newChat">＋ 新建对话</button>
      <nav class="chat-nav"><RouterLink to="/documents">▤ 管理文档</RouterLink></nav>
      <section class="conversation-panel" aria-label="对话记录">
        <p class="conversation-label">对话记录</p>
        <div class="conversation-list">
          <button v-for="session in sessions" :key="session.sessionId" :class="{ active: activeSession === session.sessionId }" @click="selectSession(session.sessionId)">
            <span class="session-title">{{ displaySessionTitle(session) }}</span>
            <time class="session-time" :datetime="session.updatedAt || session.updated_at">{{ formatSessionTime(session.updatedAt || session.updated_at) }}</time>
          </button>
        </div>
      </section>
      <button class="chat-account" @click="logout"><i>{{ initials }}</i><span><b>{{ authStore.username.value }}</b><small>退出登录</small></span><em>···</em></button>
    </aside>
    <section class="chat-workspace">
      <header class="chat-header"><div><p>AI 智能会话</p><h1>{{ activeSession ? '当前对话' : '新对话' }}</h1></div><RouterLink to="/documents">管理文档</RouterLink></header>
      <div ref="messageArea" class="message-area"><div v-if="!messages.length" class="chat-empty"><i>✦</i><h2>今天想解决什么？</h2><p>可在下方添加资料、上传文件或识别图片，再开始提问。</p></div><article v-for="(item, index) in messages" :key="index" class="chat-message" :class="{ user: item.is_user }"><span>{{ item.is_user ? '你' : 'AI' }}</span><div class="message-content" :class="{ markdown: !item.is_user }" v-html="renderMessage(item.content || '正在思考…', item.is_user)" /></article></div>
      <div v-if="selectedDocuments.length" class="document-chips"><span v-for="document in selectedDocuments" :key="document.id">▤ {{ document.name }} <button @click="removeDocument(document.id)">×</button></span></div>
      <p v-if="notice" class="chat-notice" :class="noticeType">{{ notice }}</p>
      <label class="model-selector">对话模型
        <select aria-label="选择对话模型" @change="setChatModelType($event.target.value)">
          <option value="openai">ChatGPT</option>
          <option value="zhipu">智谱 GLM</option>
        </select>
      </label>
      <form class="chat-composer" @submit.prevent="send"><button class="add-button" type="button" aria-label="添加资料或图片" @click="attachmentOpen = !attachmentOpen">＋</button><textarea v-model="question" :disabled="sending" placeholder="给 AI 发送消息" rows="1" @keydown.enter.exact.prevent="send" /><button class="send-button" :disabled="sending || !question.trim()" aria-label="发送消息" type="submit">↑</button><div v-if="attachmentOpen" class="attachment-menu"><label><input type="file" accept=".pdf,.md,.txt" @change="uploadFromChat" />⌁ <b>添加文档</b><small>从电脑上传 PDF、MD 或 TXT</small></label><button type="button" @click="openDocumentPicker">▤ <b>从资料库添加</b><small>选择已上传的知识资料</small></button><label><input type="file" accept="image/*" @change="recognizeFromChat" />◉ <b>识别图片</b><small>上传图片，获取识别结果</small></label></div></form>
      <p class="chat-disclaimer">AI 可能会出错，请核对重要信息。</p>
    </section>
  </main>
  <div v-if="pickerOpen" class="picker-backdrop" @click.self="pickerOpen = false"><section class="document-picker"><header><div><p>资料库</p><h2>添加到当前对话</h2></div><button @click="pickerOpen = false">×</button></header><p v-if="documentsLoading">正在加载资料…</p><div v-else class="picker-list"><label v-for="document in documents" :key="document.id"><input v-model="pickedIds" type="checkbox" :value="document.id" /><span><b>{{ document.name }}</b><small>{{ document.status === 'ready' ? '可检索' : '处理中' }}</small></span></label><p v-if="!documents.length">资料库还没有文档。请先上传资料。</p></div><footer><RouterLink to="/documents">管理资料库</RouterLink><button class="primary" :disabled="!pickedIds.length" @click="confirmDocuments">添加所选资料</button></footer></section></div>
</template>

<script setup>
import DOMPurify from 'dompurify'
import { marked } from 'marked'
import { computed, nextTick, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { bindDocuments, fetchDocument, fetchDocuments, fetchHistory, fetchSessionDocuments, fetchSessions, logout as logoutRequest, recognizeImage, setChatModelType, streamSessionMessage, unbindDocument, uploadDocument } from '../services/api'
import { authStore } from '../stores/auth'
const sessions = ref([]), messages = ref([]), question = ref(''), activeSession = ref(''), sending = ref(false), attachmentOpen = ref(false), pickerOpen = ref(false), documentsLoading = ref(false), documents = ref([]), pickedIds = ref([]), selectedDocuments = ref([]), notice = ref(''), noticeType = ref('info'), messageArea = ref(null)
const normalizeDocument = item => ({ id: item.document_id, name: item.file_name, status: item.parse_status || 'pending', errorMessage: item.error_message || '' })
const router = useRouter()
const initials = computed(() => authStore.username.value.slice(0, 2).toUpperCase())
const notify = (text, type = 'info') => { notice.value = text; noticeType.value = type }
const renderMessage = (content, isUser) => isUser ? DOMPurify.sanitize(content).replace(/\n/g, '<br>') : DOMPurify.sanitize(marked.parse(content, { gfm: true, breaks: true }))
const displaySessionTitle = session => String(session?.title || '未命名对话')
function formatSessionTime(value) {
  if (!value) return '更新时间未知'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return '更新时间未知'
  const now = new Date()
  const time = date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false })
  if (date.toDateString() === now.toDateString()) return `今天 ${time}`
  return `${date.getMonth() + 1}/${date.getDate()} ${time}`
}
const scrollToBottom = async () => { await nextTick(); messageArea.value?.scrollTo({ top: messageArea.value.scrollHeight, behavior: 'smooth' }) }
async function loadSessions() { try { sessions.value = (await fetchSessions()).sessions || [] } catch { notify('无法加载历史对话。', 'error') } }
async function selectSession(id) { activeSession.value = id; selectedDocuments.value = []; try { const [history, sessionDocuments] = await Promise.all([fetchHistory(id), fetchSessionDocuments(id)]); messages.value = history.history || []; selectedDocuments.value = (sessionDocuments.documents || []).map(normalizeDocument); await scrollToBottom() } catch { notify('无法加载该对话。', 'error') } }
function newChat() { activeSession.value = ''; messages.value = []; selectedDocuments.value = []; question.value = ''; notice.value = '' }
async function logout() { try { await logoutRequest() } finally { authStore.clear(); router.push('/auth') } }
async function loadDocuments() { documentsLoading.value = true; try { documents.value = ((await fetchDocuments()).documents || []).map(normalizeDocument) } catch { notify('无法加载资料库。', 'error') } finally { documentsLoading.value = false } }
async function openDocumentPicker() { attachmentOpen.value = false; pickerOpen.value = true; pickedIds.value = selectedDocuments.value.map(item => item.id); await loadDocuments() }
async function confirmDocuments() { const selected = documents.value.filter(item => pickedIds.value.includes(item.id)); selectedDocuments.value = selected; pickerOpen.value = false; const ready = selected.filter(item => item.status === 'ready'); const unavailable = selected.find(item => item.status !== 'ready'); if (activeSession.value && ready.length) { try { await bindDocuments(activeSession.value, ready.map(item => item.id)); notify(unavailable ? '可检索资料已添加；其余文档仍在处理中。' : '资料已添加到当前对话。', 'success') } catch (error) { notify(`资料绑定失败：${error.message}`, 'error') } } }
async function removeDocument(id) { const document = selectedDocuments.value.find(item => item.id === id); if (!document) return; if (!activeSession.value) { selectedDocuments.value = selectedDocuments.value.filter(item => item.id !== id); return } try { await unbindDocument(activeSession.value, id); selectedDocuments.value = selectedDocuments.value.filter(item => item.id !== id); notify(`已从当前对话移除“${document.name}”。`, 'success') } catch (error) { notify(`移除资料失败：${error.message}`, 'error') } }
const sleep = ms => new Promise(resolve => window.setTimeout(resolve, ms))
function replaceSelectedDocument(document) { selectedDocuments.value = selectedDocuments.value.map(item => item.id === document.id ? document : item) }
async function waitForDocument(document) {
  for (let attempt = 0; attempt < 90; attempt += 1) {
    await sleep(1000)
    const latest = normalizeDocument((await fetchDocument(document.id)).document)
    replaceSelectedDocument(latest)
    if (latest.status === 'ready') {
      if (activeSession.value) await bindDocuments(activeSession.value, [latest.id])
      notify(`“${latest.name}”已解析并绑定到当前会话。`, 'success')
      return latest
    }
    if (latest.status === 'failed') throw new Error(latest.errorMessage || '文档解析失败')
  }
  throw new Error('文档解析超时，请稍后在资料库查看状态')
}
async function uploadFromChat(event) { const file = event.target.files[0]; event.target.value = ''; attachmentOpen.value = false; if (!file) return; try { const document = normalizeDocument((await uploadDocument(file)).document); selectedDocuments.value = [...selectedDocuments.value, document]; notify(`正在解析“${document.name}”…`); await waitForDocument(document) } catch (error) { notify(`文档未能用于检索：${error.message}`, 'error') } }
async function recognizeFromChat(event) { const file = event.target.files[0]; event.target.value = ''; attachmentOpen.value = false; if (!file) return; notify('正在识别图片…'); try { const result = await recognizeImage(file); messages.value.push({ is_user: true, content: `请识别图片：${file.name}` }, { is_user: false, content: `图片识别结果：${result.class_name || '未识别到明确类别'}` }); await scrollToBottom(); notify('图片识别完成。', 'success') } catch (error) { notify(`图片识别失败：${error.message}`, 'error') } }
async function send() { const text = question.value.trim(); if (!text || sending.value) return; const unavailable = selectedDocuments.value.find(item => item.status !== 'ready'); if (unavailable) return notify(`“${unavailable.name}”仍在解析，完成后会自动绑定。`, 'error'); question.value = ''; sending.value = true; messages.value.push({ is_user: true, content: text }, { is_user: false, content: '' }); await scrollToBottom(); const answer = messages.value.at(-1); try { await streamSessionMessage({ sessionId: activeSession.value, question: text, documentIds: selectedDocuments.value.map(item => item.id) }, { onSession: id => { activeSession.value = id }, onChunk: async chunk => { answer.content += chunk; await scrollToBottom() }, onDone: loadSessions }) } catch (error) { answer.content = error.message || '请求未完成。' } finally { sending.value = false; await scrollToBottom() } }
onMounted(loadSessions)
</script>

